package cn.zhuatech.okr.controller; import cn.zhuatech.okr.common.ApiResponse; import cn.zhuatech.okr.dto.OkrDto.*; import cn.zhuatech.okr.service.OkrService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('OKR_MANAGER','QUALITY','ADMIN')") public class OkrAdminController {private final OkrService okr;public OkrAdminController(OkrService okr){this.okr=okr;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(okr.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<ObjectiveView>> orders(){return ApiResponse.ok(okr.objectives());}}
